class Solution:
    def minimumRelativeLoss(self, prices: List[int], queries: List[List[int]]) -> List[int]:
        import bisect
        prices.sort()
        n = len(prices)
        pre = [0] * (n + 1)
        for i, p in enumerate(prices):
            pre[i + 1] = pre[i] + p
        res = []
        for k, m in queries:
            c = bisect.bisect_right(prices, k)
            lo, hi = max(0, m - (n - c)), min(m, c)
            def F(t):
                return pre[t] + 2 * k * (m - t) - (pre[n] - pre[n - (m - t)])
            a, b = lo, hi
            while b - a > 2:
                m1 = a + (b - a) // 3
                m2 = b - (b - a) // 3
                if F(m1) <= F(m2):
                    b = m2
                else:
                    a = m1
            res.append(min(F(t) for t in range(a, b + 1)))
        return res

