class Solution {
public:
    vector<long long> minimumRelativeLoss(vector<int>& prices, vector<vector<int>>& queries) {
        sort(prices.begin(), prices.end());
        int n = prices.size();
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + prices[i];
        vector<long long> res;
        for (auto& q : queries) {
            long long k = q[0], m = q[1];
            int c = upper_bound(prices.begin(), prices.end(), (int)k) - prices.begin();
            long long lo = max(0LL, m - (n - c)), hi = min(m, (long long)c);
            auto F = [&](long long t) {
                return pre[t] + 2 * k * (m - t) - (pre[n] - pre[n - (m - t)]);
            };
            long long a = lo, b = hi;
            while (b - a > 2) {
                long long m1 = a + (b - a) / 3, m2 = b - (b - a) / 3;
                if (F(m1) <= F(m2)) b = m2; else a = m1;
            }
            long long best = LLONG_MAX;
            for (long long t = a; t <= b; t++) best = min(best, F(t));
            res.push_back(best);
        }
        return res;
    }
};

