class Solution {
    public long[] minimumRelativeLoss(int[] prices, int[][] queries) {
        Arrays.sort(prices);
        int n = prices.length;
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + prices[i];
        long[] res = new long[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            long k = queries[qi][0], m = queries[qi][1];
            int c = upperBound(prices, (int) k);
            long lo = Math.max(0, m - (n - c)), hi = Math.min(m, c);
            java.util.function.LongUnaryOperator F = t ->
                pre[(int) t] + 2 * k * (m - t) - (pre[n] - pre[n - (int)(m - t)]);
            long a = lo, b = hi;
            while (b - a > 2) {
                long m1 = a + (b - a) / 3, m2 = b - (b - a) / 3;
                if (F.applyAsLong(m1) <= F.applyAsLong(m2)) b = m2; else a = m1;
            }
            long best = Long.MAX_VALUE;
            for (long t = a; t <= b; t++) best = Math.min(best, F.applyAsLong(t));
            res[qi] = best;
        }
        return res;
    }
    private int upperBound(int[] a, int k) {
        int lo = 0, hi = a.length;
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (a[mid] <= k) lo = mid + 1; else hi = mid; }
        return lo;
    }
}

