var minimumRelativeLoss = function(prices, queries) {
    prices.sort((a, b) => a - b);
    const n = prices.length;
    const pre = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + prices[i];
    const res = [];
    for (const [k, m] of queries) {
        let c = 0, lo0 = 0, hi0 = n;
        while (lo0 < hi0) { const mid = (lo0 + hi0) >> 1; if (prices[mid] <= k) lo0 = mid + 1; else hi0 = mid; }
        c = lo0;
        const F = (t) => pre[t] + 2 * k * (m - t) - (pre[n] - pre[n - (m - t)]);
        let a = Math.max(0, m - (n - c)), b = Math.min(m, c);
        while (b - a > 2) {
            const m1 = a + Math.floor((b - a) / 3), m2 = b - Math.floor((b - a) / 3);
            if (F(m1) <= F(m2)) b = m2; else a = m1;
        }
        let best = Infinity;
        for (let t = a; t <= b; t++) best = Math.min(best, F(t));
        res.push(best);
    }
    return res;
};

